        public async void GetPersonData(RequestType requestType, object Item)
        {           
            try
            {
                var searchValues = new Dictionary<string, string>();
                searchValues.Add("token", _EkengConfiguration.Token);
                searchValues.Add("opaque", Guid.NewGuid().ToString());

                var url = _EkengConfiguration.URL;
                switch (requestType)
                {
                    case RequestType.SSN:
                        searchValues.Add("ssn", ((Models.BySSN)Item).ssn);
                        url = _EkengConfiguration.URL_SSN;
                        break;
                    case RequestType.Document:
                        searchValues.Add("type", ((Models.ByDocument)Item).type);
                        searchValues.Add("documentNumber", ((Models.ByDocument)Item).documentNumber);
                        break;
                    case RequestType.Name:
                        searchValues.Add("type", ((Models.ByName)Item).type);
                        searchValues.Add("name", ((Models.ByName)Item).name);
                        searchValues.Add("surname", ((Models.ByName)Item).surname);
                        searchValues.Add("dob", ((Models.ByName)Item).dob);
                        break;
                    default:
                        break;
                }


                _logger.Log.InfoFormat("Requesting[{0}][]: {1}", requestType, searchValues);



                var client = new HttpClient();
                request = new HttpRequestMessage(HttpMethod.Post, url) { Content = new FormUrlEncodedContent(searchValues) };
                response = client.SendAsync(request).Result;

                if (response.IsSuccessStatusCode)
                {
                    EkengResponse aVVResponse = JsonConvert.DeserializeObject<EkengResponse>(response.Content.ReadAsStringAsync().Result);

                    if (aVVResponse.status == "OK")
                    {
                        AcraUtils.OpenSSLAES256Cryptor cryptor = new OpenSSLAES256Cryptor();
                        Deserialize(requestType, aVVResponse.data);
                        // result = cryptor.DecryptString_Aes(aVVResponse.data, _EkengConfiguration.SecretKey, _EkengConfiguration.InitVector);
                        // Decode Response
                    }
                    else
                    {
                        //Error
                        result = aVVResponse.errors;
                    }
                }

                ////   Deserialize(RequestType.SSN, test_dataSSNSingle);
                //Deserialize(RequestType.SSN, xml_dataSSN);



            }
            catch (Exception ex)
            {
                _logger.Log.Error("Request ID: " + requestType + " Error: " + ex.Message);
                result = "Request Error";
                //  throw new Exception("Request Error");
            }

            //EkengResponse avvResponse = new EkengResponse();
            //avvResponse.status = "OK";
            //avvResponse.errors = null;
            //avvResponse.data = "";
            //AcraUtils.OpenSSLAES256Cryptor cryptor = new OpenSSLAES256Cryptor();
            //result = cryptor.DecryptString_Aes(avvResponse.data, _EkengConfiguration.SecretKey, _EkengConfiguration.InitVector);
            ////            // Decode Response
        }

        public enum RequestType
        {
            SSN,
            Document,
            Name
        }

        private void Deserialize(RequestType requestType, string responseData)
        {
            data = null;
            AcraUtils.OpenSSLAES256Cryptor cryptor = new OpenSSLAES256Cryptor();
            switch (requestType)
            {
                case RequestType.SSN:
                    result = cryptor.DecryptString_Aes(responseData, _EkengConfiguration.SecretKey, _EkengConfiguration.InitVector);
                    result = new string(result.Where(c => !char.IsControl(c)).ToArray());

                    XmlDocument tempXml = JsonConvert.DeserializeXmlNode(result, "data");
                    XmlSerializer serializer = new XmlSerializer(typeof(Models.PDataModel));
                    StringReader stringReader = new StringReader(tempXml.InnerXml);
                    data = (Models.PDataModel)serializer.Deserialize(stringReader);
                   
                    break;
                case RequestType.Document:
                case RequestType.Name:
                    result = cryptor.DecryptString_Aes(responseData, _EkengConfiguration.SecretKey, _EkengConfiguration.InitVector);
                    result = new string(result.Where(c => !char.IsControl(c)).ToArray());
                    data = JsonConvert.DeserializeObject<Models.PNumModel>(result);
                    break;
                default:
                    break;
            }
        }
                
                
